local RectTransform = CS.UnityEngine.RectTransform
---@type PVPArenaUtils
local PVPArenaUtils     = import('Game.Utils.PVPArenaUtils')
---@type PVPArenaComponent
local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
------------ import ------------

------------ define ------------
local NodeName = "Cell"
local NodePath = "Game.UI.PVPArena.PVPArenaHonorListRankItem"

local EmptyNodeSeasonId = -1

