function PVPArenaHonorListItem:__init()
end

function PVPArenaHonorListItem:__delete()
end

function PVPArenaHonorListItem:Awake()
    UIEventProxy.Create(self.CardGroup.gameObject).onPointerClick = Bind(self, self.OnClickCardGroupAction)
end

function PVPArenaHonorListItem:OnDestroy()
    self:RemoveListener()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end

function PVPArenaHonorListItem:AddListener()
    if self.__EventRequestSeasonRankSuccess then
        return
    end
    self.__EventRequestSeasonRankSuccess = Events.AddListener(Constants.EventNames.PVPArenaRequestSeasonRankSuccess, Bind(self, self.EventRequestSeasonRankSuccess))
end
function PVPArenaHonorListItem:RemoveListener()
    if self.__EventRequestSeasonRankSuccess then
        Events.RemoveListener(Constants.EventNames.PVPArenaRequestSeasonRankSuccess, self.__EventRequestSeasonRankSuccess)
        self.__EventRequestSeasonRankSuccess = nil
    end
end

