function PVPArenaHonorListItem:RefreshUI(historyData, index, isExpand)
    self.index    = index
    self.isExpand = isExpand
    self.seasonId = historyData.seasonId
    self:RefreshCardGroup(historyData)

    KTool.SetActive(self.SelectGroup.gameObject, isExpand)
    self:RefreshExpandNode()
end

function PVPArenaHonorListItem:RefreshCardGroup(historyData)
    local seasonId = historyData.seasonId
    local isShowCardItem = seasonId ~= EmptyNodeSeasonId
    KTool.SetActive(self.UnOpenGroup.gameObject, not isShowCardItem)
    KTool.SetActive(self.CardItem.gameObject, isShowCardItem)

    if isShowCardItem then
        self.TxtNumber.text = string.format("%02d", historyData.seasonId)
        local excludeDialogs = {
            {id = Constants.UITypeIds.PVPArenaHonorListDialog }
        }
        PVPArenaUtils.RefreshPlayerHeadNode(self.PlayerHeadNode.gameObject, historyData.playerId, historyData, excludeDialogs)

        self.TxtLV.text    = historyData.level
        self.TextName.text = historyData.name
    end
end

function PVPArenaHonorListItem:RefreshExpandNode()
    local isExpand = self.isExpand
    KTool.SetActive(self.SelectGroup.gameObject, true)

    self:FixCellSize(isExpand)

    if isExpand then
        self:AddListener()
        local seasonId = self.seasonId
        pvpArenaComponent:RequestSeasonRank(seasonId)
    else
        KTool.SetActive(self.SelectGroup.gameObject, false)
        self:RemoveListener()
    end
end

function PVPArenaHonorListItem:FixCellSize(isExpand)
    local x = isExpand and 770 or 300
    self.controller.transform:SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, x)
end

function PVPArenaHonorListItem:EventRequestSeasonRankSuccess(seasonId, seasonRank)
    if not self.isExpand then return end
    if self.seasonId ~= seasonId then return end
    if seasonRank == nil then return end

    self.seasonRank = seasonRank
    local ListView = self.ViewInfo
    if not ListView.IsListViewInit then
        ListView:InitListView(#seasonRank, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(ListView, #seasonRank)
    end
end

function PVPArenaHonorListItem:OnGetItemByIndex(listView, idx)
    if idx < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(NodeName)
    local node = GetLuaBehaviour(cell.gameObject, NodePath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        local index    = idx + 1
        local rankData = self.seasonRank[index]
        ---@type PVPArenaHonorListRankItem
        local Env = node.Env
        Env:RefreshUI(rankData)
    end
    return cell
end

